package main

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
)

const generatedHeader = `// SPDX-License-Identifier: Apache-2.0
// SPDX-FileCopyrightText: 2026 German Federal Office for Information Security (BSI) <https://www.bsi.bund.de>
// Software-Engineering: 2026 Intevation GmbH <https://intevation.de>

// Code generated by internal/generate/bare.

`

func typedSource(packageName, body string) ([]byte, error) {
	var imports []string
	for _, pkg := range []string{"v20", "v21"} {
		if strings.Contains(body, pkg+".") {
			path := "csaf/" + pkg
			imports = append(imports, fmt.Sprintf("%q", "github.com/gocsaf/csaf/v3/"+path))
		}
	}
	source := generatedHeader + "package " + packageName + "\n\n"
	if len(imports) > 0 {
		source += "import (\n" + strings.Join(imports, "\n") + "\n)\n"
	}
	return format.Source([]byte(source + body))
}

func (m *typedModel) emitModel(packageName string) ([]byte, error) {
	var out bytes.Buffer
	for _, node := range m.structures {
		fmt.Fprintf(&out, "// %s contains common fields and optional version-specific details.\ntype %s struct {\n", node.name, node.name)
		for _, f := range node.fields {
			if f.common != nil {
				optional := f.versions[0].omitEmpty || f.versions[1].omitEmpty
				fmt.Fprintf(&out, "%s %s %s\n", f.name, typedName(f.common), jsonTag(f.jsonName, optional))
			}
		}
		for version := range 2 {
			if len(details(node, version)) > 0 {
				fmt.Fprintf(&out, "*%s%dDetails\n", node.name, 20+version)
			}
		}
		out.WriteString("}\n")
		for version := range 2 {
			fs := details(node, version)
			if len(fs) == 0 {
				continue
			}
			fmt.Fprintf(&out, "// %s%dDetails contains fields specific to CSAF 2.%d.\ntype %s%dDetails struct {\n", node.name, 20+version, version, node.name, 20+version)
			for _, f := range fs {
				typ, err := wireType(f.versions[version].typ, 20+version, m.models[version])
				if err != nil {
					return nil, err
				}
				fmt.Fprintf(&out, "%s %s %s\n", f.name, typ, jsonTag(f.jsonName, f.versions[version].omitEmpty))
			}
			out.WriteString("}\n")
			for _, f := range fs {
				suffix := ""
				if f.versions[1-version].typ != nil {
					suffix = fmt.Sprint(20 + version)
				}
				typ, err := wireType(f.versions[version].typ, 20+version, m.models[version])
				if err != nil {
					return nil, err
				}
				fmt.Fprintf(&out, "// Get%s%s reports whether the matching version details are present.\nfunc (v *%s) Get%s%s() (%s,bool) {\n if v == nil || v.%s%dDetails == nil { var zero %s; return zero,false }; return v.%s%dDetails.%s,true\n}\n", f.name, suffix, node.name, f.name, suffix, typ, node.name, 20+version, typ, node.name, 20+version, f.name)
			}
		}
	}
	return typedSource(packageName, out.String())
}
